import { Routes } from '@angular/router';

// Pages étudiant
import { StudentHomeComponent } from './pages/student/student-home.component';
import { JoinClassComponent } from './pages/student/join-class.component';

// Pages prof
import { ProfDashboardComponent } from './pages/prof-dashboard/prof-dashboard.component';
import { ClassroomListComponent } from './pages/classrooms/classroom-list.component';

export const routes: Routes = [
  { path: '', redirectTo: 'student', pathMatch: 'full' },

  // 🧑‍🎓 Espace étudiant
  { path: 'student', component: StudentHomeComponent },
  { path: 'student/join', component: JoinClassComponent },

  // 🧑‍🏫 Espace professeur
  { path: 'dashboard', component: ProfDashboardComponent },
  { path: 'dashboard/classes', component: ClassroomListComponent }
];
